import { describe, expect, it } from 'vitest';
import {
  carriesGeneratedMarker,
  generatedHeader,
  generatedJsonNote,
  withoutVersion,
} from './header.js';

describe('generated headers', () => {
  it('names the version and the extension file', () => {
    expect(generatedHeader('#', '1.2.3', 'x.toml')).toBe(
      '# Generated by Talos 1.2.3. Do not edit: extend it in x.toml, which may only tighten it.\n',
    );
    expect(generatedJsonNote('1.2.3')).toBe('Generated by Talos 1.2.3. Do not edit.');
  });

  it('finds the marker on the first lines only', () => {
    expect(carriesGeneratedMarker(generatedHeader('//', '1.0.0'))).toBe(true);
    expect(carriesGeneratedMarker(`{\n  "//": "${generatedJsonNote('1.0.0')}"\n}\n`)).toBe(true);
    expect(carriesGeneratedMarker('a\nb\nc\n// Generated by Talos 1.0.0.\n')).toBe(false);
  });

  it('leaves the version out, whatever its shape', () => {
    for (const version of ['0.1.0', '1.2.3-rc.1', '0.0.0-test']) {
      expect(withoutVersion(generatedHeader('--', version, 'a.lua'))).toBe(
        withoutVersion(generatedHeader('--', '9.9.9', 'a.lua')),
      );
      expect(withoutVersion(`{ "//": "${generatedJsonNote(version)}" }`)).toBe(
        '{ "//": "Generated by Talos. Do not edit." }',
      );
    }
    expect(withoutVersion('# Generated by Talos 1.0.0.')).toBe('# Generated by Talos.');
    expect(withoutVersion('no header here')).toBe('no header here');
  });
});
